able-column label="传输统计" min-width="145"><template #default="{ row }">{{ row.latest_attempt_summary?.transport ? `请求 ${row.latest_attempt_summary.transport.requests ?? 0} · 重试 ${row.latest_attempt_summary.transport.retries ?? 0}` : '等待下一次同步' }}</template></el-table-column><el-table-column label="诊断" min-width="210"><template #default="{ row }">{{ row.notice ?? (row.age_seconds !== null && row.age_seconds !== undefined ? `距今 ${Math.round(row.age_seconds / 3600)} 小时` : '-') }}</template></el-table-column></el-table><el-table :data="strategyGovernance.contracts ?? []" size="small" max-height="220"><el-table-column prop="strategy_key" label="策略族"/><el-table-column prop="strategy_version" label="版本"/><el-table-column prop="status" label="状态"/><el-table-column prop="approved_by" label="批准人"/></el-table></el-card>
